{
  "claims": [
    {
      "gene_symbol": "IGF2BP1",
      "confidence": 0.85,
      "cited_ids": [
        "pub:32154328",
        "pub:28652347"
      ],
      "rationale": "Functional studies demonstrated that IGF2BP1 overexpression induces fetal hemoglobin expression in cultured human adult erythroblasts and restores HbF in erythroid cells from patients with beta-hemoglobinopathies."
    },
    {
      "gene_symbol": "HIC2",
      "confidence": 0.7,
      "cited_ids": [
        "pub:29061339"
      ],
      "rationale": "HIC2 was shown to regulate developmentally timed isoform switching during cardiovascular maturation (pub:29061339), providing strong mechanistic precedent for a conserved role in regulating developmental fetal globin switching."
    }
  ],
  "refusals": [
    {
      "gene_symbol": "ASH1L",
      "reason": "Although identified as a candidate globin regulator in a family genetic study (pub:27434206), pre-cutoff evidence lacked functional demonstration that perturbing ASH1L alters fetal hemoglobin in erythroid cells."
    },
    {
      "gene_symbol": "CHD3",
      "reason": "Pre-cutoff evidence implicates the NuRD complex paralog CHD4 rather than CHD3 in fetal hemoglobin repression, with no functional evidence supporting CHD3 as an HbF regulator."
    },
    {
      "gene_symbol": "DNMT1",
      "reason": "Pre-cutoff literature lacks functional evidence demonstrating that specific perturbation of DNMT1 regulates fetal hemoglobin in human erythroid cells without confounding cytotoxicity."
    },
    {
      "gene_symbol": "DNMT3A",
      "reason": "Pre-cutoff evidence links DNMT3A to hematopoietic stem cell biology and leukemia rather than specific regulation of fetal hemoglobin."
    },
    {
      "gene_symbol": "DNMT3B",
      "reason": "Pre-cutoff studies focus on general DNA methylation and malignancy, with no functional evidence establishing a role for DNMT3B in HbF regulation."
    },
    {
      "gene_symbol": "EIF2AK2",
      "reason": "Pre-cutoff literature implicates EIF2AK1 (HRI) in fetal hemoglobin regulation, while EIF2AK2 lacks functional evidence supporting a role in HbF control."
    },
